struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float3 background(float2 uv, float t)
{
    float3 col;
    float angle = atan2(uv.y - 0.5f, uv.x - 0.5f);
    float radius = length(uv - 0.5f);
    col.r = 0.5f + 0.5f * sin(angle * 3.0f + t);
    col.g = 0.5f + 0.5f * sin(angle * 2.0f + t * 1.5f + 2.094f);
    col.b = 0.5f + 0.5f * sin(radius * 10.0f - t * 2.0f + 4.189f);
    col *= 0.8f + 0.2f * sin(uv.x * 12.0f + t);
    return col;
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001f;
    float2 uv = i.uv;
    float3 col = background(uv, t);
    float2 center = uv - 0.5f;
    float dist = length(center);
    float vignette = 1.0f - smoothstep(0.3f, 0.75f, dist);
    col *= vignette;
    return float4(col, 1.0f);
}
